Ação Chamada Corpo Cadastrar <code>POST /material/</code> → 201 <code>{ "titulo", "tipo", "link", "descricao"? }</code> Editar <code>PUT /material/{id}</code> → 200 mesmo corpo Excluir <code>DELETE /material/{id}</code> → 204 — <ul> <li><code>tipo</code> aceita <code>"foto"</code>, <code>"video"</code> ou <code>"documento"</code>.</li> <li><code>link</code> é o link de compartilhamento do Drive e precisa começar com <code>https://</code>.</li> <li><code>titulo</code> não pode ficar em branco.</li> <li>Erro de validação responde 422, administrador de setor recebe 403 e material inexistente responde 404.</li> </ul> <p>O arquivo do Drive precisa estar compartilhado com a conta institucional, a mesma da galeria.</p> <pre><code>// src/services/api/materialApi.js
import { api } from "../api";

/** GET /material/ (publico). tipo: "foto" | "video" | "documento" | undefined */
export async function listarMateriais(tipo) {
  const { data } = await api.get("/material/", { params: tipo ? { tipo } : {} });
  return data;
}

/** POST /material/ (superadmin) */
export async function criarMaterial(material) {
  const { data } = await api.post("/material/", material);
  return data;
}

/** PUT /material/{id} (superadmin) */
export async function atualizarMaterial(id, material) {
  const { data } = await api.put(`/material/${id}`, material);
  return data;
}

/** DELETE /material/{id} (superadmin) */
export async function deletarMaterial(id) {
  await api.delete(`/material/${id}`);
}
</code></pre>
